program TowersOfHanoi;

var
  diskCount: integer;

procedure Hanoi(n, fromPeg, toPeg, auxPeg: integer);
begin
  if n = 1 then
    writeln('Move disk ', n, ' from ', fromPeg, ' to ', toPeg)
  else
  begin
    Hanoi(n - 1, fromPeg, auxPeg, toPeg);
    writeln('Move disk ', n, ' from ', fromPeg, ' to ', toPeg);
    Hanoi(n - 1, auxPeg, toPeg, fromPeg)
  end
end;

begin
  diskCount := 3;
  writeln('Towers of Hanoi for ', diskCount, ' disks:');
  Hanoi(diskCount, 1, 3, 2)
end.

SERVICE "helloService";
BEGIN
  CASE httpVerb OF
    httpVerb.post: RETURN src;
    httpVerb.get: RETURN "hello, world";
  END;
END;

ROUTER "helloService-http" INPUT "helloService.in" DESCRIPTION "Return hello, world for GET" ENABLED TRUE SERVICE "helloService" BEGIN
  OUTPUT "helloService.out"
    WHEN "IF upper(httpVerb) = 'GET' THEN output := 1 ELSE output := 0;"
    TRANSFORM "output := 'hello, world';";
END;

Deployment:
1) Set-Location .\aggregator
2) $env:ESP32_NODE_NAME='neptune.child1'
3) npm run deploy:esp32:hello-service

The deploy script resolves neptune.child1 through http://127.0.0.1:4000/api/nodes and deploys to the resolved ESP32 host.

